function M.isCore(heroId)
  heroId = tostring(heroId or "")
  for _, id in ipairs(M.CORE) do
    if id == heroId then return true end
  end
  return false
end

function M.get(heroId)
  return M.HEROES[tostring(heroId or "")]
end

function M.isDeprecated(heroId)
  local h = M.get(heroId)
  return h ~= nil and h.deprecated == true
end

function M.isUnlocked(_heroId, _mission)
  if M.isDeprecated(_heroId) then return false end
  if M.PLAYTEST_ALL_UNLOCKED then return true end
  return true
end

function M.hireCost(heroId)
  local h = M.get(heroId)
  if not h then return 999 end
  return tonumber(h.hireTnb) or 0
end

function M.hireKmCost(heroId)
  local h = M.get(heroId)
  if not h then return 0 end
  return tonumber(h.hireKm or h["hireKm$"]) or 0
end

function M.isMentor(heroId)
  heroId = tostring(heroId or "")
  if heroId == "" then return false end
  local h = M.get(heroId)
  if h and (h.isMentor == true or h.mentor == true) then return true end
  if M.MENTOR_PRODUCTS[heroId] then return true end
  local trait = h and tostring(h.heroTrait or h.trait or "") or ""
  return trait == "wheelie_mentor" or trait == "scout_tech" or trait == "factory_mentor"
end

function M.mentorProducts(heroId)
  return M.MENTOR_PRODUCTS[tostring(heroId or "")]
end

function M.defaultAutoPick()
  return { "verse", "grath", "odessa" }
end

return M
